node --input-type=module - <<'NODE'
import {limitFunction} from './index.js';
const calls = [];
const limited = limitFunction(async (...args) => {
	calls.push(args);
	return args.join(':');
}, {concurrency: 1});
console.log(JSON.stringify({result: await limited('a', 42), calls}));
NODE
Expected result "a:42" and calls [["a",42]]; actual result is "" and calls is [[]].

node --input-type=module - <<'NODE'
import pLimit from './index.js';
const limit = pLimit({concurrency: 1});
const running = limit(() => new Promise(resolve => setTimeout(resolve, 40)));
const pending = limit(() => 'pending-result');
await Promise.resolve();
limit.clearQueue();
console.log(await Promise.race([
	pending.then(value => ({settled: true, status: 'fulfilled', value}), error => ({settled: true, status: 'rejected', name: error?.name})),
	new Promise(resolve => setTimeout(() => resolve({settled: false}), 20)),
]));
await running;
NODE
Also assert that pLimit({concurrency: 1, rejectOnClear: 0}) throws TypeError.

